def choose_move(observation):
    dx = 0
    dy = 0
    if not isinstance(observation, dict):
        return [dx, dy]
    wx = observation.get("grid_width", 0)
    wy = observation.get("grid_height", 0)
    px = observation.get("self_position", {}).get("x", 0)
    py = observation.get("self_position", {}).get("y", 0)
    ox = observation.get("opponent_position", {}).get("x", 0)
    oy = observation.get("opponent_position", {}).get("y", 0)

    # Basic avoidance: if opponent adjacent, move away if possible
    if abs(ox - px) <= 1 and abs(oy - py) <= 1:
        if ox > px and px > 0:
            dx = -1
        elif ox < px and px < wx - 1:
            dx = 1
        if oy > py and py > 0:
            dy = -1
        elif oy < py and py < wy - 1:
            dy = 1
        if dx == 0 and dy == 0:
            dx = -1 if px > 0 else 1

    # Move towards nearest resource if available
    resources = observation.get("resources", [])
    if isinstance(resources, list) and resources:
        best = None
        best_dist = None
        for r in resources:
            rx = r.get("x")
            ry = r.get("y")
            if rx is None or ry is None:
                continue
            dist = (rx - px) * (rx - px) + (ry - py) * (ry - py)
            if best_dist is None or dist < best_dist:
                best_dist = dist
                best = (rx, ry)
        if best is not None:
            rx, ry = best
            if rx > px:
                dx = 1
            elif rx < px:
                dx = -1
            if ry > py:
                dy = 1
            elif ry < py:
                dy = -1

    # Clamp to grid
    nx = px + dx
    ny = py + dy
    if nx < 0 or ny < 0 or nx >= wx or ny >= wy:
        dx, dy = 0, 0

    return [dx, dy]
